From d8d0a6ce6869d6f0d5241fd64e4214c6f7daf0a2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:45:00 +0100
Subject: [PATCH] backends/drm: let software dimming reach black

Dimming was applied to the brightness factor before the 5 nit floor, so
a fully dimmed screen stayed a visible grey. Dimming now scales the
reference luminance after the floor, down to just above the black level.

BUG: 518672
---
 src/backends/drm/drm_output.cpp | 6 ++++--
 1 file changed, 4 insertions(+), 2 deletions(-)

diff --git a/src/backends/drm/drm_output.cpp b/src/backends/drm/drm_output.cpp
index 3cab4c13b6..35ec3c6f29 100644
--- a/src/backends/drm/drm_output.cpp
+++ b/src/backends/drm/drm_output.cpp
@@ -451,8 +451,9 @@ std::shared_ptr<ColorDescription> DrmOutput::createColorDescription(const State
     if ((!next.brightnessDevice && next.allowSdrSoftwareBrightness) || effectiveHdr) {
         brightnessFactor = next.currentBrightness.value_or(next.brightnessSetting);
     }
+    double dimmingFactor = 1.0;
     if (!next.brightnessDevice || next.brightnessDevice->usesDdcCi() || effectiveHdr) {
-        brightnessFactor *= next.currentDimming;
+        dimmingFactor = next.currentDimming;
     }

     double minLuminance = 0.01;
@@ -529,7 +530,8 @@ std::shared_ptr<ColorDescription> DrmOutput::createColorDescription(const State
     }

     Colorimetry sdrColorimetry = Colorimetry::BT709.interpolateGamutTo(nativeColorimetry, next.sdrGamutWideness);
-    const double effectiveReferenceLuminance = 5 + (maxReferenceLuminance - 5) * brightnessFactor;
+    // dimming may go all the way down to the black level, but not below it
+    const double effectiveReferenceLuminance = std::max((5 + (maxReferenceLuminance - 5) * brightnessFactor) * dimmingFactor, minLuminance + 0.0001);
     return std::make_shared<ColorDescription>(ColorDescription{
         containerColorimetry,
         transferFunction,
-- 
