From dbc75b47ab90dffbd858cea33228723f87406b8a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:45:00 +0100
Subject: [PATCH] Add an option to dim the screen to black

Automatic dimming always stopped at 30%, and turning the screen off cuts
the signal, so TVs show "no signal" instead of a black screen. A new "To
black" choice next to "Dim automatically" dims fully and keeps it on.

BUG: 518672
---
 PowerDevilProfileSettings.kcfg        |   3 +
 daemon/actions/bundled/dimdisplay.cpp |  13 ++-
 daemon/actions/bundled/dimdisplay.h   |   1 +
 kcm/ui/ProfileConfig.qml              | 132 ++++++++++++++++----------
 4 files changed, 94 insertions(+), 55 deletions(-)

diff --git a/PowerDevilProfileSettings.kcfg b/PowerDevilProfileSettings.kcfg
index 0ad1848ca..5a2894659 100644
--- a/PowerDevilProfileSettings.kcfg
+++ b/PowerDevilProfileSettings.kcfg
@@ -51,6 +51,9 @@ SPDX-License-Identifier: CC0-1.0
                 PowerDevil::ProfileDefaults::defaultDimDisplayIdleTimeoutSec(mParamProfileId, mParamIsMobile)
             </default>
         </entry>
+        <entry name="DimDisplayToBlack" type="Bool">
+            <default>false</default>
+        </entry>
         <entry name="TurnOffDisplayWhenIdle" type="Bool">
             <default type="code">
                 PowerDevil::ProfileDefaults::defaultTurnOffDisplayWhenIdle()
diff --git a/daemon/actions/bundled/dimdisplay.cpp b/daemon/actions/bundled/dimdisplay.cpp
index 0ff7be9a5..721a42372 100644
--- a/daemon/actions/bundled/dimdisplay.cpp
+++ b/daemon/actions/bundled/dimdisplay.cpp
@@ -61,11 +61,7 @@ void DimDisplay::onIdleTimeout(std::chrono::milliseconds timeout)

     qCDebug(POWERDEVIL) << "DimDisplay: triggered on idle timeout, dimming";

-    // Dim brightness to 30% of the original. 30% is chosen arbitrarily based on the
-    // assumption that e.g. 50% may be too bright for returning user to notice that
-    // the screen is going to go off, while 20% may be too dark to be able to read
-    // something on the screen.
-    core()->screenBrightnessController()->setDimmingRatio(DIMMING_ID, 0.3);
+    core()->screenBrightnessController()->setDimmingRatio(DIMMING_ID, m_dimmingRatio);

     m_oldKeyboardBrightness = core()->keyboardBrightnessController()->brightness();
     setKeyboardBrightnessHelper(0);
@@ -105,7 +101,14 @@ bool DimDisplay::loadAction(const PowerDevil::ProfileSettings &profileSettings)
         return false;
     }

+    // Dim brightness to 30% of the original, unless the user wants a black screen that stays on.
+    // 30% is chosen arbitrarily based on the assumption that e.g. 50% may be too bright for
+    // returning user to notice that the screen is going to go off, while 20% may be too dark
+    // to be able to read something on the screen.
+    m_dimmingRatio = profileSettings.dimDisplayToBlack() ? 0.0 : 0.3;
+
     if (m_dimmed) {
+        core()->screenBrightnessController()->setDimmingRatio(DIMMING_ID, m_dimmingRatio);
         if (profileSettings.useProfileSpecificKeyboardBrightness()) {
             m_oldKeyboardBrightness = profileSettings.keyboardBrightness();
         }
diff --git a/daemon/actions/bundled/dimdisplay.h b/daemon/actions/bundled/dimdisplay.h
index 2aa37907b..9b26dbf80 100644
--- a/daemon/actions/bundled/dimdisplay.h
+++ b/daemon/actions/bundled/dimdisplay.h
@@ -34,6 +34,7 @@ private:
     void setKeyboardBrightnessHelper(int keyboardBrightness);

     std::chrono::milliseconds m_dimOnIdleTime{0};
+    double m_dimmingRatio = 0.3;

     int m_oldKeyboardBrightness = 0;

